    ondeAssistir: { link: "x", assinatura: [{ id: 8, nome: "Netflix", logoPath: null }], aluguel: [], compra: [{ id: 2, nome: "Apple TV", logoPath: null }] },
    ...extra };
}

export function dadosFalsos(sobrescrever: Partial<DadosUsuario> = {}): DadosUsuario {
